using Microsoft.Extensions.AI;
using Microsoft.Extensions.AI.Evaluation;
using Microsoft.Extensions.AI.Evaluation.Quality;
using Microsoft.Extensions.AI.Evaluation.Reporting;

namespace MyApp.Evaluation;

[TestClass]
public sealed class EvaluationTests
{
    private static ReportingConfiguration? s_reportingConfiguration;

    [AssemblyInitialize]
    public static void Initialize(TestContext context)
    {
        s_reportingConfiguration = CreateReportingConfiguration();
    }

    [AssemblyCleanup]
    public static async Task Cleanup()
    {
        if (s_reportingConfiguration is not null)
        {
            await s_reportingConfiguration.DisposeAsync();
        }
    }

    private static ReportingConfiguration CreateReportingConfiguration()
    {
        var path = Path.Combine(
            Path.GetDirectoryName(typeof(EvaluationTests).Assembly.Location)!,
            "evaluation-report");

        return DiskBasedReportingConfiguration.Create(storageRootPath: path);
    }

    [TestMethod]
    public async Task Chat_responds_relevantly()
    {
        await using var scenario =
            await s_reportingConfiguration!.CreateScenarioRunAsync(
                scenarioName: nameof(Chat_responds_relevantly));

        var chatClient = scenario.GetOrCreateChatClient(
            createChatClient: () => CreateChatClient());

        var messages = new List<ChatMessage>
        {
            new(ChatRole.User, "What is the capital of France?")
        };

        var response = await chatClient.GetResponseAsync(messages);

        var evaluators = new IEvaluator[]
        {
            new RelevanceTruthAndCompletenessEvaluator()
        };

        await scenario.EvaluateAsync(
            messages,
            response,
            evaluators);

        scenario.AssertAllNumericMetricsAreHigherThanOrEqualTo(3);
    }

    [TestMethod]
    public async Task Chat_responds_coherently()
    {
        await using var scenario =
            await s_reportingConfiguration!.CreateScenarioRunAsync(
                scenarioName: nameof(Chat_responds_coherently));

        var chatClient = scenario.GetOrCreateChatClient(
            createChatClient: () => CreateChatClient());

        var messages = new List<ChatMessage>
        {
            new(ChatRole.User, "Explain in one sentence what .NET Aspire is.")
        };

        var response = await chatClient.GetResponseAsync(messages);

        var evaluators = new IEvaluator[]
        {
            new CoherenceEvaluator(),
            new FluencyEvaluator()
        };

        await scenario.EvaluateAsync(
            messages,
            response,
            evaluators);

        scenario.AssertAllNumericMetricsAreHigherThanOrEqualTo(3);
    }

    private static IChatClient CreateChatClient()
    {
        var endpoint = Environment.GetEnvironmentVariable("AZURE_OPENAI_ENDPOINT")
            ?? throw new InvalidOperationException(
                "Set the AZURE_OPENAI_ENDPOINT environment variable.");

        var model = Environment.GetEnvironmentVariable("AZURE_OPENAI_MODEL") ?? "gpt-4o-mini";

        return new Azure.AI.OpenAI.AzureOpenAIClient(
            new Uri(endpoint),
            new Azure.Identity.DefaultAzureCredential())
            .GetChatClient(model)
            .AsIChatClient();
    }
}

